#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_autoe;
uniform float amzp_autob;
uniform float amzp_autor;
uniform float amzp_XXA;
uniform float amzp_XXB;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_invert;
uniform float amzp_autos;
uniform float amzp_autop;
uniform float amzp_XXC;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.)*amzLayerToScreen()).xy; }
        float distLine(float2 p, float2 a, float2 b){
         float2 pa = p - a;
            float2 ba = b - a;
            float t = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
            return length(pa - ba*t);
        }
        float line(float2 p, float2 a, float2 b){
         float d = distLine(p, a, b);
            float m = smoothstep(0.03, 0.01, d);
            float d2 = length(a - b);
            m *= smoothstep(1.2, 0.8, d2) * 0.5 + smoothstep(0.05, 0.03, abs(d2 - 0.75));
            return m;
        }
        float distTriangle(in float2 p, in float2 p0, in float2 p1, in float2 p2 )
        {
         float2 e0 = p1 - p0;
         float2 e1 = p2 - p1;
         float2 e2 = p0 - p2;
         float2 v0 = p - p0;
         float2 v1 = p - p1;
         float2 v2 = p - p2;
         float2 pq0 = v0 - e0*clamp( dot(v0,e0)/dot(e0,e0), 0.0, 1.0 );
         float2 pq1 = v1 - e1*clamp( dot(v1,e1)/dot(e1,e1), 0.0, 1.0 );
         float2 pq2 = v2 - e2*clamp( dot(v2,e2)/dot(e2,e2), 0.0, 1.0 );
            float s = sign( e0.x*e2.y - e0.y*e2.x );
            float2 d = min( min( float2( dot( pq0, pq0 ), s*(v0.x*e0.y-v0.y*e0.x) ),
                               float2( dot( pq1, pq1 ), s*(v1.x*e1.y-v1.y*e1.x) )),
                               float2( dot( pq2, pq2 ), s*(v2.x*e2.y-v2.y*e2.x) ));
         return -sqrt(d.x)*sign(d.y);
        }
        float triangle(float2 p, float2 a, float2 b, float2 c){
         float d = distTriangle(p, a, b, c);
            float m = smoothstep(0.03, 0.01, d);
            float d2 = length(a - b);
            m *= smoothstep(1.2, 0.8, d2) * 0.5 + smoothstep(0.05, 0.03, abs(d2 - 0.75));
            return m;
        }
        float N21(float2 p){
         p = fract(p * float2(233.34, 851.73));
            p += dot(p, p + 23.45);
            return fract(p.x * p.y);
        }
        float2 N22(float2 p){
         float n = N21(p);
            return float2(n, N21(p + n));
        }
        float2 getPos(float2 id, float2 offset){
            float FEVO = (amzp_autoe>0.5)? amzp_XXA+(time*0.5) : amzp_XXA;
            float2 n = N22(id + offset) * FEVO;
            return offset + sin(n) * 0.4;
        }
        float amzLocal_layer(float2 uv){
         float2 gv = fract(uv) - 0.5;
            float2 id = floor(uv);
            float2 p[9];
            int i = 0;
            for(float y = -1.0; y <= 1.0; y++){
             for(float x = -1.0; x <= 1.0; x++){
                 p[i++] = getPos(id, float2(x, y));
             }
            }
            float t = (amzp_autob>0.5)? (amzp_XXB+time*0.5) * 10.0 : amzp_XXB * 10.0;
            float m = 0.0;
            for(int i = 0; i < 9; i++){
             m += line(gv, p[4], p[i]);
                float2 j = (p[i] - gv) * 20.0;
                float sparkle = 1.0 / dot(j, j);
                m += sparkle * (sin(t + fract(p[i].x) * 10.0) * 0.5 + 0.5);
                for(int yi= i + 1; yi < 9; yi++){
              for(int zi= yi + 1; zi < 9; zi++){
                        float len1 = abs(length(p[i] - p[yi]));
                        float len2 = abs(length(p[yi] - p[zi]));
                        float len3 = abs(length(p[i] - p[zi]));
                        if((len1 + len2 + len3) < 2.8){
                         m += triangle(gv, p[i], p[yi], p[zi]) * 0.8;
                        }
              }
             }
            }
            m += line(gv, p[1], p[3]);
            m += line(gv, p[1], p[5]);
            m += line(gv, p[7], p[3]);
            m += line(gv, p[7], p[5]);
            return m;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        float ROTATE = (amzp_autor>0.5)? amzp_angle+(time*2.5) : amzp_angle;
        satriyaid *= rot2m((0.0+ROTATE)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
            float2 uv = satriyaid;
            float m = 0.0;
            float mm = 0.0;
            float t = (amzp_autop>0.5)? (amzp_XXC+time*0.5) * 0.1 : amzp_XXC * 0.1;
            float s = sin(t);
            float c = cos(t);
            float2x2 rot = float2x2(c, -s, s, c);
            for(float i = 0.0; i < 1.0; i += 16.0){
                float z = fract(i + t);
                float amzLocal_size = mix(10.0, 0.5, z);
                float fade = smoothstep(0.0, 0.5, z) * smoothstep(1.0, 0.8, z);
                m += amzLocal_layer(uv * amzLocal_size + i * 20.0) * fade;
                mm += amzLocal_layer(uv * amzLocal_size + i * 20.0);
            }
            float3 base = sin(t * 5.0 * float3(0.345, 0.456, 0.567)) * 0.4 + 0.6;
            float3 col = (amzp_autos>0.5)?m * base : mm * amzp_color2.rgb;
            fragColor = float4(col,0.0);
            if((amzp_invert>0.5)) { fragColor = 1.-fragColor; }
     float4 factor = newLayer(amzp_color1,fragColor);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= 1.0;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
